#pragma once
#include <ktx.h>
#include "render_api/D3D12Include.hpp"

namespace aZero::RenderAPI
{
	enum class TEXTURE_FORMAT { RGBA8_UNORM, RGBA8_UNORM_SRGB, BC7_UNORM, BC7_UNORM_SRGB, RGB32_FLOAT, RGB32_UINT, RGB32_SINT, RGBA32_FLOAT, RGBA32_UINT, RGBA32_SINT, RGBA16_FLOAT, RGBA16_UINT, RGBA16_SINT, RGBA16_UNORM, D24S8_UINT, UNKNOWN };

	static inline TEXTURE_FORMAT FromVK_Format(ktx_uint32_t format)
	{
		switch (format)
		{
			// VK_FORMAT_R8G8B8A8_UNORM
		case 37:
			return TEXTURE_FORMAT::RGBA8_UNORM;
			// VK_FORMAT_R8G8B8A8_SRGB 
		case 43:
			return TEXTURE_FORMAT::RGBA8_UNORM;
		case 145:
			return TEXTURE_FORMAT::BC7_UNORM;
		case 146:
			return TEXTURE_FORMAT::BC7_UNORM_SRGB;
		default:
			return TEXTURE_FORMAT::UNKNOWN;
		}
	}

	static inline TEXTURE_FORMAT FromDX_Format(DXGI_FORMAT format)
	{
		switch (format)
		{
		case DXGI_FORMAT::DXGI_FORMAT_R8G8B8A8_UNORM:
			return TEXTURE_FORMAT::RGBA8_UNORM;
		case DXGI_FORMAT::DXGI_FORMAT_R8G8B8A8_UNORM_SRGB:
			return TEXTURE_FORMAT::RGBA8_UNORM_SRGB;
		case DXGI_FORMAT::DXGI_FORMAT_BC7_UNORM:
			return TEXTURE_FORMAT::BC7_UNORM;
		case DXGI_FORMAT::DXGI_FORMAT_BC7_UNORM_SRGB:
			return TEXTURE_FORMAT::BC7_UNORM_SRGB;
		case DXGI_FORMAT::DXGI_FORMAT_R32G32B32_FLOAT:
			return TEXTURE_FORMAT::RGB32_FLOAT;
		case DXGI_FORMAT::DXGI_FORMAT_R32G32B32_UINT:
			return TEXTURE_FORMAT::RGB32_UINT;
		case DXGI_FORMAT::DXGI_FORMAT_R32G32B32_SINT:
			return TEXTURE_FORMAT::RGB32_SINT;
		case DXGI_FORMAT::DXGI_FORMAT_R32G32B32A32_FLOAT:
			return TEXTURE_FORMAT::RGBA32_FLOAT;
		case DXGI_FORMAT::DXGI_FORMAT_R32G32B32A32_UINT:
			return TEXTURE_FORMAT::RGBA32_UINT;
		case DXGI_FORMAT::DXGI_FORMAT_R32G32B32A32_SINT:
			return TEXTURE_FORMAT::RGBA32_SINT;
		case DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_FLOAT:
			return TEXTURE_FORMAT::RGBA16_FLOAT;
		case DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_UINT:
			return TEXTURE_FORMAT::RGBA16_UINT;
		case DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_SINT:
			return TEXTURE_FORMAT::RGBA16_SINT;
		case DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_UNORM:
			return TEXTURE_FORMAT::RGBA16_UNORM;
		case DXGI_FORMAT::DXGI_FORMAT_D24_UNORM_S8_UINT:
			return TEXTURE_FORMAT::D24S8_UINT;
		default:
			return TEXTURE_FORMAT::UNKNOWN;
		}
	}

	static inline DXGI_FORMAT ToDX_Format(TEXTURE_FORMAT format)
	{
		switch (format)
		{
		case TEXTURE_FORMAT::RGBA8_UNORM:
			return DXGI_FORMAT::DXGI_FORMAT_R8G8B8A8_UNORM;
		case TEXTURE_FORMAT::RGBA8_UNORM_SRGB:
			return DXGI_FORMAT::DXGI_FORMAT_R8G8B8A8_UNORM_SRGB;
		case TEXTURE_FORMAT::BC7_UNORM:
			return DXGI_FORMAT::DXGI_FORMAT_BC7_UNORM;
		case TEXTURE_FORMAT::BC7_UNORM_SRGB:
			return DXGI_FORMAT::DXGI_FORMAT_BC7_UNORM_SRGB;
		case TEXTURE_FORMAT::RGB32_FLOAT:
			return DXGI_FORMAT::DXGI_FORMAT_R32G32B32_FLOAT;
		case TEXTURE_FORMAT::RGB32_UINT:
			return DXGI_FORMAT::DXGI_FORMAT_R32G32B32_UINT;
		case TEXTURE_FORMAT::RGB32_SINT:
			return DXGI_FORMAT::DXGI_FORMAT_R32G32B32_SINT;
		case TEXTURE_FORMAT::RGBA32_FLOAT:
			return DXGI_FORMAT::DXGI_FORMAT_R32G32B32A32_FLOAT;
		case TEXTURE_FORMAT::RGBA32_UINT:
			return DXGI_FORMAT::DXGI_FORMAT_R32G32B32A32_UINT;
		case TEXTURE_FORMAT::RGBA32_SINT:
			return DXGI_FORMAT::DXGI_FORMAT_R32G32B32A32_SINT;
		case TEXTURE_FORMAT::RGBA16_FLOAT:
			return DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_FLOAT;
		case TEXTURE_FORMAT::RGBA16_UINT:
			return DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_UINT;
		case TEXTURE_FORMAT::RGBA16_SINT:
			return DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_SINT;
		case TEXTURE_FORMAT::RGBA16_UNORM:
			return DXGI_FORMAT::DXGI_FORMAT_R16G16B16A16_UNORM;
		case TEXTURE_FORMAT::D24S8_UINT:
			return DXGI_FORMAT::DXGI_FORMAT_D24_UNORM_S8_UINT;
		default:
			return DXGI_FORMAT::DXGI_FORMAT_UNKNOWN;
		}
	}

	static inline std::string Format_To_String(TEXTURE_FORMAT format)
	{
		switch (format)
		{
		case TEXTURE_FORMAT::RGBA8_UNORM:
			return "RGBA8_UNORM";
		case TEXTURE_FORMAT::RGBA8_UNORM_SRGB:
			return "RGBA8_UNORM_SRGB";
		case TEXTURE_FORMAT::BC7_UNORM:
			return "BC7_UNORM";
		case TEXTURE_FORMAT::BC7_UNORM_SRGB:
			return "BC7_UNORM_SRGB";
		case TEXTURE_FORMAT::RGB32_FLOAT:
			return "RGB32_FLOAT";
		case TEXTURE_FORMAT::RGB32_UINT:
			return "RGB32_UINT";
		case TEXTURE_FORMAT::RGB32_SINT:
			return "RGB32_SINT";
		case TEXTURE_FORMAT::RGBA32_FLOAT:
			return "RGBA32_FLOAT";
		case TEXTURE_FORMAT::RGBA32_UINT:
			return "RGBA32_UINT";
		case TEXTURE_FORMAT::RGBA32_SINT:
			return "RGBA32_SINT";
		case TEXTURE_FORMAT::RGBA16_FLOAT:
			return "RGBA16_FLOAT";
		case TEXTURE_FORMAT::RGBA16_UINT:
			return "RGBA16_UINT";
		case TEXTURE_FORMAT::RGBA16_SINT:
			return "RGBA16_SINT";
		case TEXTURE_FORMAT::RGBA16_UNORM:
			return "RGBA16_UNORM";
		case TEXTURE_FORMAT::D24S8_UINT:
			return "D24S8_UINT";
		default:
			return "UNKNOWN";
		}
	}
}